#!/usr/bin/env bash
set -euo pipefail
source "$(cd "$(dirname "${BASH_SOURCE[0]}")/../lib" && pwd)/common.sh"
command_exists buf && { log_ok "buf $(buf --version) ya instalado"; exit 0; }
OS="$(detect_os)"; case "$(uname -m)" in x86_64) ARCH=x86_64;; arm64|aarch64) ARCH=aarch64;; *) log_err 'Arquitectura no soportada'; exit 1;; esac; case "$OS" in linux) PLATFORM=Linux;; macos) PLATFORM=Darwin;; *) exit 1;; esac
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT; download https://api.github.com/repos/bufbuild/buf/releases/latest "$TMP/release.json"; VERSION="$(grep -m1 '"tag_name"' "$TMP/release.json" | cut -d'"' -f4 | sed 's/^v//')"; [ -n "$VERSION" ] || { log_err 'No se pudo determinar versión de buf'; exit 1; }; TARBALL="buf-${PLATFORM}-${ARCH}.tar.gz"; download "https://github.com/bufbuild/buf/releases/download/v${VERSION}/${TARBALL}" "$TMP/$TARBALL"; tar -xzf "$TMP/$TARBALL" -C "$TMP"; BIN="$(find "$TMP" -type f -name buf -perm -u+x | head -n1)"; [ -n "$BIN" ] || { log_err 'No se encontró binario buf'; exit 1; }; if [ -w /usr/local/bin ]; then install -m 0755 "$BIN" /usr/local/bin/buf; elif [ "${NO_SUDO:-0}" = "1" ]; then mkdir -p "$HOME/.local/bin"; install -m 0755 "$BIN" "$HOME/.local/bin/buf"; ensure_path_line 'export PATH="$HOME/.local/bin:$PATH"'; export PATH="$HOME/.local/bin:$PATH"; else run_sudo install -m 0755 "$BIN" /usr/local/bin/buf; fi; log_ok "buf $(buf --version) instalado"
